module.exports = [
{ e: "🐌", art: { b: "🐌", s: ["🌧️", "🥬", "🌀", "✨"], c: ["#4A5A2A", "#A0A05A"] },
pt: { h: "Na manhã depois da chuva, Nina encontrou um caracol subindo devagarinho pelo vidro da porta. Por trás do vidro, dava para ver a barriga dele fazendo ondinhas. “Ele está andando por cima de uma gosma que ele mesmo faz”, explicou o vovô. “E sabia que ele tem milhares de dentinhos?”", t: "Caracóis e lesmas", f: "Os caracóis e as lesmas são moluscos, parentes dos polvos e dos mexilhões. Eles andam com um único pé muscular, fazendo ondas, e soltam uma gosma que ajuda a deslizar, grudar e proteger o corpo. Os caracóis carregam uma concha, que cresce junto com eles em forma de espiral. As lesmas são parecidas, mas sem concha.", x: "A boca do caracol tem uma língua especial, chamada rádula, coberta de milhares de dentinhos minúsculos, que funciona como uma lixa para raspar folhas! E os olhos de muitos caracóis ficam na ponta das anteninhas compridas.", s: ["Nos dias secos, o caracol se fecha na concha com uma tampinha de gosma seca e espera a chuva.", "A concha do caracol cresce sempre a partir da abertura, aumentando a espiral.", "Os caracóis e as lesmas gostam de umidade e saem mais à noite ou depois da chuva."], ex: { t: "Observando o pé do caracol", m: "um caracol de jardim (encontrado com um adulto), um pote ou prato de plástico transparente, uma folha de alface, uma lupa", p: ["Coloque o caracol com delicadeza sobre o plástico transparente, com uma folhinha de alface por perto.", "Levante o plástico e olhe por baixo com a lupa: dá para ver as ondinhas do pé enquanto ele anda!", "Repare na trilha brilhante de gosma que ele deixa. Depois de observar, devolva o caracol ao lugar onde ele estava e lave bem as mãos."] }, at: "Cartão 21: o caracol", m: "cartões, lápis de cor", p: ["Desenhe um caracol com a concha em espiral e os olhinhos na ponta das antenas.", "Desenhe a trilha brilhante que ele deixa para trás.", "Escreva: “Molusco, parente do polvo!”."], q: "Se você carregasse a sua casa nas costas, como ela seria?" },
en: { h: "The morning after the rain, Nina found a snail slowly climbing up the glass door. From the other side of the glass, she could see its belly making little waves. “It's moving on top of slime it makes itself,” Grandpa explained. “And did you know it has thousands of tiny teeth?”", t: "Snails and slugs", f: "Snails and slugs are mollusks, relatives of octopuses and mussels. They move on a single muscular foot that ripples in waves, and they release slime that helps them glide, stick and protect their bodies. Snails carry a shell that grows with them in a spiral shape. Slugs are similar, but without a shell.", x: "A snail's mouth has a special tongue called a radula, covered with thousands of tiny teeth, that works like sandpaper for scraping leaves! And many snails have their eyes on the tips of their long tentacles.", s: ["On dry days, a snail seals itself into its shell with a little door of dried slime and waits for rain.", "A snail's shell always grows from the opening, making the spiral bigger.", "Snails and slugs like moisture and come out more at night or after rain."], ex: { t: "Watching a snail's foot", m: "a garden snail (found with a grown-up), a clear plastic container or plate, a lettuce leaf, a magnifying glass", p: ["Gently place the snail on the clear plastic, with a little piece of lettuce nearby.", "Lift the plastic and look underneath with the magnifying glass: you can see the waves of its foot as it moves!", "Notice the shiny slime trail it leaves. After watching, return the snail to where you found it and wash your hands well."] }, at: "Card 21: the snail", m: "cards, colored pencils", p: ["Draw a snail with a spiral shell and eyes on the tips of its tentacles.", "Draw the shiny trail it leaves behind.", "Write: “A mollusk, cousin of the octopus!”"], q: "If you carried your house on your back, what would it look like?" },
es: { h: "La mañana después de la lluvia, Nina encontró un caracol subiendo despacito por el vidrio de la puerta. Del otro lado del vidrio se veía su panza haciendo ondas. “Está caminando sobre una baba que él mismo hace”, explicó el abuelo. “¿Y sabías que tiene miles de dientitos?”", t: "Caracoles y babosas", f: "Los caracoles y las babosas son moluscos, parientes de los pulpos y los mejillones. Caminan con un único pie musculoso que hace ondas, y sueltan una baba que los ayuda a deslizarse, pegarse y proteger el cuerpo. Los caracoles llevan un caparazón, que crece con ellos en forma de espiral. Las babosas son parecidas, pero sin caparazón.", x: "¡La boca del caracol tiene una lengua especial, llamada rádula, cubierta de miles de dientitos diminutos, que funciona como una lija para raspar hojas! Y los ojos de muchos caracoles están en la punta de los tentáculos largos.", s: ["En los días secos, el caracol se encierra en el caparazón con una tapita de baba seca y espera la lluvia.", "El caparazón del caracol crece siempre desde la abertura, agrandando la espiral.", "A los caracoles y las babosas les gusta la humedad y salen más de noche o después de la lluvia."], ex: { t: "Observando el pie del caracol", m: "un caracol de jardín (encontrado con un adulto), un recipiente o plato de plástico transparente, una hoja de lechuga, una lupa", p: ["Pon el caracol con delicadeza sobre el plástico transparente, con una hojita de lechuga cerca.", "Levanta el plástico y mira desde abajo con la lupa: ¡se ven las ondas del pie mientras camina!", "Fíjate en el rastro brillante de baba que deja. Después de observar, devuelve el caracol al lugar donde estaba y lávate bien las manos."] }, at: "Tarjeta 21: el caracol", m: "tarjetas, lápices de colores", p: ["Dibuja un caracol con el caparazón en espiral y los ojitos en la punta de los tentáculos.", "Dibuja el rastro brillante que deja atrás.", "Escribe: “¡Molusco, pariente del pulpo!”."], q: "Si llevaras tu casa en la espalda, ¿cómo sería?" } },

{ e: "🐛", art: { b: "🐛", s: ["🦶", "🔢", "🍂", "🌀"], c: ["#5A1B1B", "#B04A3A"] },
pt: { h: "Leo encontrou um bichinho comprido e cheio de perninhas, que se enrolou como uma mola quando foi tocado. “É uma centopeia? Tem cem pés?”, perguntou. O vovô riu: “Esse é um piolho-de-cobra! E, apesar dos nomes, quase nenhum desses bichos tem exatamente cem ou mil pés. Vamos contar?”", t: "Centopeias e piolhos-de-cobra", f: "As centopeias e os piolhos-de-cobra são miriápodes, palavra que quer dizer “muitos pés”. As centopeias têm um par de patas em cada pedacinho do corpo, são rápidas e caçam outros bichinhos. Os piolhos-de-cobra, ou embuás, têm dois pares de patas em cada pedacinho, são lentos e comem folhas e madeira podre, ajudando a reciclar a floresta.", x: "Em 2021, cientistas descobriram na Austrália, bem fundo debaixo da terra, um piolho-de-cobra com 1.306 patas! Foi o primeiro bicho encontrado com mais de mil pés de verdade.", s: ["As centopeias sempre têm um número ímpar de pares de patas, como 15, 21 ou 23 pares.", "Quando se assustam, os piolhos-de-cobra se enrolam e alguns soltam um cheirinho ruim.", "As patas se movem em ondas, uma depois da outra, como uma “ola” no estádio."], ex: { t: "Centopeia humana", m: "3 a 6 pessoas, um quintal ou sala livre", p: ["Façam uma fila, cada um segurando nos ombros da pessoa da frente. Vocês são uma centopeia!", "Tentem andar juntos, primeiro devagar e depois mais rápido, sem se soltar. Contem quantos pés a centopeia tem.", "Agora tentem fazer uma “ola”: cada um levanta o pé direito logo depois da pessoa da frente. É assim que as patas de uma centopeia se movem!"] }, at: "Cartão 22: os muitos-pés", m: "cartões, lápis de cor", p: ["Desenhe uma centopeia e um piolho-de-cobra lado a lado e mostre as diferenças.", "Conte e escreva quantas patas você desenhou em cada um.", "Escreva: “1.306 patas: o recorde!”."], q: "Se você tivesse muitas pernas, que esporte seria mais fácil e qual seria mais difícil?" },
en: { h: "Leo found a long critter with lots of little legs, which curled up like a spring when touched. “Is it a centipede? Does it have a hundred feet?” he asked. Grandpa laughed: “This one is a millipede! And despite their names, almost none of these critters has exactly a hundred or a thousand feet. Shall we count?”", t: "Centipedes and millipedes", f: "Centipedes and millipedes are myriapods, a word meaning “many feet.” Centipedes have one pair of legs on each segment of their body, are fast and hunt other little critters. Millipedes have two pairs of legs on each segment, are slow and eat leaves and rotting wood, helping recycle the forest.", x: "In 2021, scientists in Australia discovered, deep underground, a millipede with 1,306 legs! It was the first animal ever found with truly more than a thousand feet.", s: ["Centipedes always have an odd number of leg pairs, like 15, 21 or 23 pairs.", "When they're scared, millipedes curl up, and some give off a bad smell.", "Their legs move in waves, one after another, like a stadium wave."], ex: { t: "Human centipede", m: "3 to 6 people, a clear yard or room", p: ["Make a line, each person holding the shoulders of the person in front. You're a centipede!", "Try walking together, slowly at first and then faster, without letting go. Count how many feet your centipede has.", "Now try doing a “wave”: each person lifts their right foot just after the person in front. That's how a centipede's legs move!"] }, at: "Card 22: the many-feet", m: "cards, colored pencils", p: ["Draw a centipede and a millipede side by side and show the differences.", "Count and write how many legs you drew on each one.", "Write: “1,306 legs: the record!”"], q: "If you had lots of legs, which sport would be easier and which would be harder?" },
es: { h: "Leo encontró un bichito largo y lleno de patitas, que se enrolló como un resorte cuando lo tocó. “¿Es un ciempiés? ¿Tiene cien pies?”, preguntó. El abuelo se rió: “¡Este es un milpiés! Y, a pesar de los nombres, casi ninguno de estos bichos tiene exactamente cien o mil pies. ¿Contamos?”", t: "Ciempiés y milpiés", f: "Los ciempiés y los milpiés son miriápodos, palabra que quiere decir “muchos pies”. Los ciempiés tienen un par de patas en cada pedacito del cuerpo, son rápidos y cazan otros bichitos. Los milpiés tienen dos pares de patas en cada pedacito, son lentos y comen hojas y madera podrida, ayudando a reciclar el bosque.", x: "¡En 2021, científicos descubrieron en Australia, muy hondo bajo la tierra, un milpiés con 1.306 patas! Fue el primer animal encontrado con más de mil pies de verdad.", s: ["Los ciempiés siempre tienen un número impar de pares de patas, como 15, 21 o 23 pares.", "Cuando se asustan, los milpiés se enrollan y algunos sueltan un olorcito feo.", "Las patas se mueven en ondas, una después de la otra, como una “ola” en el estadio."], ex: { t: "Ciempiés humano", m: "de 3 a 6 personas, un patio o una sala libre", p: ["Hagan una fila, cada uno agarrado de los hombros de la persona de adelante. ¡Son un ciempiés!", "Intenten caminar juntos, primero despacio y después más rápido, sin soltarse. Cuenten cuántos pies tiene el ciempiés.", "Ahora intenten hacer una “ola”: cada uno levanta el pie derecho justo después de la persona de adelante. ¡Así se mueven las patas de un ciempiés!"] }, at: "Tarjeta 22: los muchos-pies", m: "tarjetas, lápices de colores", p: ["Dibuja un ciempiés y un milpiés uno al lado del otro y muestra las diferencias.", "Cuenta y escribe cuántas patas dibujaste en cada uno.", "Escribe: “1.306 patas: ¡el récord!”."], q: "Si tuvieras muchas piernas, ¿qué deporte sería más fácil y cuál más difícil?" } },

{ e: "🎭", art: { b: "🦋", s: ["👁️", "🐝", "🎭", "🦉"], c: ["#2A1B4A", "#C2A03A"] },
pt: { h: "No jardim, Leo saiu correndo de uma “abelha” listrada de amarelo e preto. O vovô olhou de perto e riu: “Pode voltar! É uma mosca disfarçada de abelha. Ela não tem ferrão, mas usa a fantasia para os passarinhos acharem que ela pica!”", t: "Mimetismo: os imitadores", f: "Alguns insetos se protegem imitando bichos perigosos ou que têm gosto ruim. Isso se chama mimetismo. Moscas listradas parecem abelhas e vespas. Algumas borboletas copiam as cores de outras que são venenosas. E a borboleta-coruja, que vive no Brasil, tem nas asas um desenho que parece o olho enorme de uma coruja.", x: "Algumas lagartas, quando se assustam, inflam a parte da frente do corpo e mostram desenhos que parecem a cabeça de uma cobra, com olhos e tudo! Os passarinhos levam um susto e vão embora.", s: ["Os desenhos de olhos nas asas assustam os predadores ou fazem eles atacarem a asa em vez da cabeça.", "Algumas aranhas imitam formigas, mexendo as patinhas da frente como se fossem antenas.", "Os imitadores enganam usando cores, formas e até o jeito de se mexer."], ex: { t: "Olhos que assustam", m: "papel, tesoura, lápis de cor, uma vareta ou canudo, fita", p: ["Recorte duas borboletas iguais de papel. Numa, desenhe dois olhos grandes e redondos nas asas; na outra, só manchinhas.", "Prenda cada borboleta numa vareta e mostre de repente, uma de cada vez, para alguém da família.", "Qual deu mais susto? Os olhos fazem o predador pensar que tem um bicho grande olhando para ele!"] }, at: "Cartão 23: os imitadores", m: "cartões, lápis de cor", p: ["Desenhe lado a lado uma abelha de verdade e a mosca que a imita. Consegue ver as diferenças?", "Desenhe a borboleta-coruja com o olho nas asas.", "Escreva: “Fantasia para se proteger!”."], q: "Se você pudesse usar uma fantasia para se proteger, de que bicho seria?" },
en: { h: "In the garden, Leo ran away from a yellow-and-black striped “bee.” Grandpa looked closely and laughed: “You can come back! It's a fly dressed up as a bee. It has no stinger, but it uses the costume so birds think it stings!”", t: "Mimicry: the copycats", f: "Some insects protect themselves by imitating dangerous animals or animals that taste bad. This is called mimicry. Striped flies look like bees and wasps. Some butterflies copy the colors of others that are poisonous. And the owl butterfly, found in Central and South America, has a pattern on its wings that looks like an owl's huge eye.", x: "Some caterpillars, when they're startled, puff up the front of their bodies and show patterns that look like a snake's head, eyes and all! Birds get a fright and leave.", s: ["Eye patterns on wings scare predators or make them attack the wing instead of the head.", "Some spiders imitate ants, waving their front legs as if they were antennae.", "Copycats fool others with colors, shapes and even the way they move."], ex: { t: "Scary eyes", m: "paper, scissors, colored pencils, a stick or straw, tape", p: ["Cut out two identical paper butterflies. On one, draw two big round eyes on the wings; on the other, just small spots.", "Tape each butterfly to a stick and suddenly show them, one at a time, to someone in your family.", "Which one was scarier? The eyes make a predator think a big animal is staring at it!"] }, at: "Card 23: the copycats", m: "cards, colored pencils", p: ["Draw a real bee and the fly that imitates it side by side. Can you see the differences?", "Draw the owl butterfly with the eye on its wings.", "Write: “A costume for protection!”"], q: "If you could wear a costume to protect yourself, which animal would it be?" },
es: { h: "En el jardín, Leo salió corriendo de una “abeja” rayada de amarillo y negro. El abuelo la miró de cerca y se rió: “¡Puedes volver! Es una mosca disfrazada de abeja. No tiene aguijón, pero usa el disfraz para que los pájaros crean que pica.”", t: "Mimetismo: los imitadores", f: "Algunos insectos se protegen imitando a animales peligrosos o de mal sabor. Eso se llama mimetismo. Algunas moscas rayadas parecen abejas y avispas. Algunas mariposas copian los colores de otras que son venenosas. Y la mariposa búho, que vive en América Central y del Sur, tiene en las alas un dibujo que parece el ojo enorme de un búho.", x: "¡Algunas orugas, cuando se asustan, inflan la parte de adelante del cuerpo y muestran dibujos que parecen la cabeza de una serpiente, con ojos y todo! Los pájaros se asustan y se van.", s: ["Los dibujos de ojos en las alas asustan a los depredadores o hacen que ataquen el ala en lugar de la cabeza.", "Algunas arañas imitan a las hormigas, moviendo las patitas de adelante como si fueran antenas.", "Los imitadores engañan con colores, formas y hasta con su manera de moverse."], ex: { t: "Ojos que asustan", m: "papel, tijera, lápices de colores, una varita o pajita, cinta", p: ["Recorta dos mariposas iguales de papel. En una, dibuja dos ojos grandes y redondos en las alas; en la otra, solo manchitas.", "Pega cada mariposa a una varita y muéstralas de golpe, de a una, a alguien de la familia.", "¿Cuál asustó más? ¡Los ojos hacen que el depredador piense que un animal grande lo está mirando!"] }, at: "Tarjeta 23: los imitadores", m: "tarjetas, lápices de colores", p: ["Dibuja una al lado de la otra una abeja de verdad y la mosca que la imita. ¿Ves las diferencias?", "Dibuja la mariposa búho con el ojo en las alas.", "Escribe: “¡Un disfraz para protegerse!”."], q: "Si pudieras usar un disfraz para protegerte, ¿de qué animal sería?" } },

{ e: "📜", art: { b: "🐝", s: ["📜", "🌳", "🏠", "⬢"], c: ["#5A4A1B", "#C2A04A"] },
pt: { h: "Debaixo do telhado da varanda, o vovô mostrou um ninho cinzento e redondo, preso por um cabinho. “Não vamos chegar perto, é das vespas”, avisou. “Mas olhem daqui: ele é feito de papel! As vespas inventaram o papel muito antes das pessoas.”", t: "As vespas, fabricantes de papel", f: "Muitas vespas constroem ninhos de papel. Elas raspam fibras de madeira de troncos e cercas, mastigam e misturam com saliva, formando uma pasta. Depois, espalham essa pasta em camadas finas, que secam e viram papel. Além disso, as vespas são caçadoras importantes: controlam lagartas e outros insetos que estragam plantações.", x: "Por volta de 1719, um cientista francês chamado Réaumur observou as vespas e sugeriu que as pessoas também poderiam fazer papel com madeira. Hoje, a maior parte do papel do mundo é feita assim!", s: ["Existem milhares de espécies de vespas, e muitas são tão pequenas que nem picam pessoas.", "Algumas vespas ajudam a polinizar flores, como as do figo.", "Se encontrar um ninho de vespas, mantenha distância e chame um adulto."], ex: { t: "Papel de vespa", m: "papel higiênico ou guardanapo, água, cola branca, uma tigela, uma peneira ou pano, um adulto", p: ["Rasgue o papel em pedacinhos, coloque na tigela com água e amasse com as mãos até virar uma pasta, como as vespas mastigando.", "Misture uma colherzinha de cola, escorra o excesso de água e espalhe a pasta bem fininha sobre a peneira ou um pano.", "Deixe secar um ou dois dias: você fez papel reciclado do jeito das vespas!"] }, at: "Cartão 24: a vespa", m: "cartões, lápis de cor, um pedacinho do seu papel reciclado", p: ["Desenhe um ninho de vespas pendurado num galho, com as casinhas por dentro.", "Cole um pedacinho do papel que você fez no cartão.", "Escreva: “As vespas inventaram o papel!”."], q: "Que outras invenções humanas você acha que vieram da natureza?" },
en: { h: "Under the porch roof, Grandpa pointed to a round gray nest hanging by a little stalk. “We won't get close, it belongs to wasps,” he warned. “But look from here: it's made of paper! Wasps invented paper long before people did.”", t: "Wasps, the papermakers", f: "Many wasps build paper nests. They scrape wood fibers from trunks and fences, chew them and mix them with saliva into a paste. Then they spread the paste in thin layers, which dry into paper. Wasps are also important hunters: they control caterpillars and other insects that damage crops.", x: "Around 1719, a French scientist named Réaumur watched wasps and suggested that people could make paper from wood too. Today, most of the paper in the world is made that way!", s: ["There are thousands of species of wasps, and many are so tiny they can't even sting people.", "Some wasps help pollinate flowers, like fig flowers.", "If you find a wasp nest, keep your distance and tell a grown-up."], ex: { t: "Wasp paper", m: "toilet paper or napkins, water, white glue, a bowl, a strainer or cloth, a grown-up", p: ["Tear the paper into small pieces, put them in the bowl with water and squish them with your hands until they turn into a paste, like wasps chewing.", "Mix in a small spoonful of glue, drain the extra water and spread the paste very thin over the strainer or a cloth.", "Let it dry for a day or two: you made recycled paper the wasp way!"] }, at: "Card 24: the wasp", m: "cards, colored pencils, a small piece of your recycled paper", p: ["Draw a wasp nest hanging from a branch, with the little cells inside.", "Glue a small piece of the paper you made onto the card.", "Write: “Wasps invented paper!”"], q: "What other human inventions do you think came from nature?" },
es: { h: "Debajo del techo del porche, el abuelo mostró un nido gris y redondo, colgado de un cabito. “No nos vamos a acercar, es de avispas”, avisó. “Pero miren desde acá: ¡está hecho de papel! Las avispas inventaron el papel mucho antes que las personas.”", t: "Las avispas, fabricantes de papel", f: "Muchas avispas construyen nidos de papel. Raspan fibras de madera de troncos y cercas, las mastican y las mezclan con saliva, formando una pasta. Después la extienden en capas finas, que se secan y se convierten en papel. Además, las avispas son cazadoras importantes: controlan orugas y otros insectos que arruinan los cultivos.", x: "¡Alrededor de 1719, un científico francés llamado Réaumur observó a las avispas y propuso que las personas también podían hacer papel con madera! Hoy, la mayor parte del papel del mundo se hace así.", s: ["Hay miles de especies de avispas, y muchas son tan chiquitas que ni siquiera pican a las personas.", "Algunas avispas ayudan a polinizar flores, como las de la higuera.", "Si encuentras un nido de avispas, mantén la distancia y avísale a un adulto."], ex: { t: "Papel de avispa", m: "papel higiénico o servilletas, agua, plasticola, un bol, un colador o un paño, un adulto", p: ["Rompe el papel en pedacitos, ponlo en el bol con agua y aplástalo con las manos hasta que sea una pasta, como las avispas masticando.", "Mezcla una cucharadita de plasticola, escurre el agua que sobra y extiende la pasta bien finita sobre el colador o un paño.", "Déjalo secar uno o dos días: ¡hiciste papel reciclado al estilo de las avispas!"] }, at: "Tarjeta 24: la avispa", m: "tarjetas, lápices de colores, un pedacito de tu papel reciclado", p: ["Dibuja un nido de avispas colgado de una rama, con las celditas por dentro.", "Pega en la tarjeta un pedacito del papel que hiciste.", "Escribe: “¡Las avispas inventaron el papel!”."], q: "¿Qué otros inventos humanos crees que vinieron de la naturaleza?" } },

{ e: "🛡️", art: { b: "🦗", s: ["🛡️", "🎈", "🌳", "📏"], c: ["#4A3A1B", "#A08A4A"] },
pt: { h: "No tronco de uma árvore, Nina encontrou uma casquinha marrom em forma de inseto, vazia e rachada nas costas. “Cadê o bicho?”, perguntou. “Ele saiu de dentro!”, explicou o vovô. “É a roupa velha de uma cigarra. Os insetos têm uma armadura que não estica, então, para crescer, eles precisam trocar de armadura.”", t: "A armadura dos insetos", f: "Os insetos não têm ossos por dentro, como nós. Eles têm um exoesqueleto: uma armadura dura por fora do corpo, que protege e segura os músculos. Mas essa armadura não cresce. Por isso, de tempos em tempos, o inseto faz uma nova armadura mole por baixo, racha a velha e sai de dentro dela. Isso se chama muda.", x: "As cigarras de algumas espécies passam anos debaixo da terra, como ninfas, chupando a seiva das raízes. Na América do Norte, existem cigarras que ficam 13 ou 17 anos enterradas e depois saem todas juntas, aos milhões!", s: ["Logo depois da muda, o inseto fica mole e esbranquiçado, e precisa se esconder até a armadura endurecer.", "As cigarras machos cantam vibrando membranas no corpo, como pequenos tambores.", "A armadura dos insetos é feita de uma substância chamada quitina."], ex: { t: "Crescendo dentro da armadura", m: "uma bexiga, um tubo de papel feito com uma folha enrolada, fita adesiva", p: ["Enrole uma folha de papel formando um tubo e feche com só um pedacinho de fita: é a armadura.", "Coloque a bexiga vazia dentro do tubo e comece a encher devagar.", "A bexiga cresce, aperta a armadura até ela abrir! É assim que o inseto precisa rachar a armadura velha para continuar crescendo."] }, at: "Cartão 25: a muda", m: "cartões, lápis de cor", p: ["Desenhe uma cigarra saindo da casca velha, presa num tronco.", "Desenhe ao lado a casca vazia, rachada nas costas.", "Escreva: “Para crescer, troca de armadura!”."], q: "Que roupa ou sapato você já perdeu porque cresceu?" },
en: { h: "On a tree trunk, Nina found a brown, insect-shaped shell, empty and split down the back. “Where's the bug?” she asked. “It climbed out!” Grandpa explained. “It's a cicada's old outfit. Insects have armor that doesn't stretch, so to grow, they have to change their armor.”", t: "Insect armor", f: "Insects don't have bones inside like we do. They have an exoskeleton: hard armor on the outside of the body that protects it and holds the muscles. But that armor doesn't grow. So, from time to time, the insect makes a new soft armor underneath, splits the old one and crawls out of it. This is called molting.", x: "Some species of cicadas spend years underground as nymphs, sucking sap from roots. In North America, there are cicadas that stay buried for 13 or 17 years and then all come out together, by the millions!", s: ["Right after molting, an insect is soft and pale and has to hide until its armor hardens.", "Male cicadas sing by vibrating membranes on their bodies, like tiny drums.", "Insect armor is made of a substance called chitin."], ex: { t: "Growing inside the armor", m: "a balloon, a paper tube made from a rolled-up sheet, tape", p: ["Roll a sheet of paper into a tube and close it with just one small piece of tape: that's the armor.", "Put the empty balloon inside the tube and start blowing it up slowly.", "The balloon grows and squeezes the armor until it pops open! That's how an insect has to split its old armor to keep growing."] }, at: "Card 25: molting", m: "cards, colored pencils", p: ["Draw a cicada climbing out of its old shell on a tree trunk.", "Next to it, draw the empty shell, split down the back.", "Write: “To grow, it changes its armor!”"], q: "What clothes or shoes have you outgrown?" },
es: { h: "En el tronco de un árbol, Nina encontró una cáscara marrón con forma de insecto, vacía y rajada en la espalda. “¿Dónde está el bicho?”, preguntó. “¡Salió de adentro!”, explicó el abuelo. “Es la ropa vieja de una chicharra. Los insectos tienen una armadura que no se estira, así que, para crecer, tienen que cambiar de armadura.”", t: "La armadura de los insectos", f: "Los insectos no tienen huesos por dentro, como nosotros. Tienen un exoesqueleto: una armadura dura por fuera del cuerpo, que protege y sostiene los músculos. Pero esa armadura no crece. Por eso, cada tanto, el insecto hace una armadura nueva y blanda por debajo, raja la vieja y sale de adentro. Eso se llama muda.", x: "¡Las chicharras de algunas especies pasan años bajo la tierra, como ninfas, chupando la savia de las raíces! En América del Norte hay chicharras que pasan 13 o 17 años enterradas y después salen todas juntas, por millones.", s: ["Justo después de la muda, el insecto queda blando y blanquecino, y tiene que esconderse hasta que la armadura se endurezca.", "Las chicharras macho cantan haciendo vibrar membranas del cuerpo, como pequeños tambores.", "La armadura de los insectos está hecha de una sustancia llamada quitina."], ex: { t: "Creciendo dentro de la armadura", m: "un globo, un tubo de papel hecho con una hoja enrollada, cinta adhesiva", p: ["Enrolla una hoja de papel formando un tubo y ciérralo con un solo pedacito de cinta: es la armadura.", "Pon el globo desinflado dentro del tubo y empieza a inflarlo despacio.", "¡El globo crece y aprieta la armadura hasta que se abre! Así el insecto tiene que rajar la armadura vieja para seguir creciendo."] }, at: "Tarjeta 25: la muda", m: "tarjetas, lápices de colores", p: ["Dibuja una chicharra saliendo de su cáscara vieja, agarrada a un tronco.", "Dibuja al lado la cáscara vacía, rajada en la espalda.", "Escribe: “¡Para crecer, cambia de armadura!”."], q: "¿Qué ropa o zapatos te quedaron chicos porque creciste?" } },

{ e: "🔗", art: { b: "🌿", s: ["🐛", "🐦", "🦊", "☀️"], c: ["#2A5A2A", "#7AB04A"] },
pt: { h: "Leo perguntou para que serviam os insetos, já que alguns picam e outros comem as plantas. O vovô pegou papel e fita: “Vamos fazer uma corrente para descobrir. Sem os insetos, muitos elos dessa corrente se soltariam!”", t: "Quem come quem: os insetos na cadeia alimentar", f: "Os insetos são comida para muitos animais: passarinhos, sapos, lagartos, morcegos, peixes e até alguns mamíferos, como o tamanduá, que come milhares de formigas e cupins por dia. A planta pega energia do Sol, a lagarta come a planta, o passarinho come a lagarta e o gavião come o passarinho. Isso se chama cadeia alimentar.", x: "Em muitos lugares do mundo, as pessoas também comem insetos! Cerca de 2 bilhões de pessoas têm insetos no cardápio, como os gafanhotos no México e a içá, a rainha da saúva, em algumas regiões do Brasil.", s: ["Um tamanduá-bandeira pode comer dezenas de milhares de formigas e cupins num só dia.", "Os filhotes de muitos passarinhos são alimentados quase só com insetos.", "Quando os insetos diminuem, os animais que dependem deles também sofrem."], ex: { t: "Corrente da vida", m: "tiras de papel, fita ou cola, lápis de cor", p: ["Em cada tira de papel, desenhe um ser vivo: Sol, planta, lagarta, passarinho e gavião.", "Monte uma corrente de papel na ordem certa, ligando quem é comido a quem come.", "Agora tire o elo da lagarta: o que acontece com o passarinho e o gavião? A corrente se desfaz! Todos dependem uns dos outros."] }, at: "Cartão 26: a cadeia alimentar", m: "cartões, lápis de cor", p: ["Desenhe uma cadeia alimentar com setas, começando pelo Sol.", "Desenhe um tamanduá comendo formigas.", "Escreva: “Sem insetos, a corrente quebra!”."], q: "Qual animal você acha que mais sentiria falta dos insetos se eles sumissem?" },
en: { h: "Leo asked what insects were good for, since some bite and others eat plants. Grandpa grabbed paper and tape: “Let's make a chain to find out. Without insects, many links in this chain would fall apart!”", t: "Who eats whom: insects in the food chain", f: "Insects are food for many animals: birds, frogs, lizards, bats, fish and even some mammals, like the anteater, which eats thousands of ants and termites a day. A plant gets energy from the Sun, a caterpillar eats the plant, a bird eats the caterpillar and a hawk eats the bird. This is called a food chain.", x: "In many places around the world, people eat insects too! About 2 billion people have insects on the menu, like grasshoppers in Mexico and roasted leafcutter ant queens in some regions of Brazil.", s: ["A giant anteater can eat tens of thousands of ants and termites in a single day.", "The babies of many birds are fed almost entirely on insects.", "When insects decline, the animals that depend on them suffer too."], ex: { t: "Chain of life", m: "strips of paper, tape or glue, colored pencils", p: ["On each strip of paper, draw a living thing: Sun, plant, caterpillar, bird and hawk.", "Make a paper chain in the right order, linking what gets eaten to what eats it.", "Now remove the caterpillar link: what happens to the bird and the hawk? The chain falls apart! Everyone depends on each other."] }, at: "Card 26: the food chain", m: "cards, colored pencils", p: ["Draw a food chain with arrows, starting with the Sun.", "Draw an anteater eating ants.", "Write: “No insects, the chain breaks!”"], q: "Which animal do you think would miss insects the most if they disappeared?" },
es: { h: "Leo preguntó para qué servían los insectos, si algunos pican y otros se comen las plantas. El abuelo agarró papel y cinta: “Hagamos una cadena para descubrirlo. ¡Sin los insectos, muchos eslabones de esta cadena se soltarían!”", t: "Quién come a quién: los insectos en la cadena alimentaria", f: "Los insectos son comida para muchos animales: pájaros, ranas, lagartijas, murciélagos, peces y hasta algunos mamíferos, como el oso hormiguero, que come miles de hormigas y termitas por día. La planta toma energía del Sol, la oruga come la planta, el pájaro come la oruga y el halcón come al pájaro. Eso se llama cadena alimentaria.", x: "¡En muchos lugares del mundo, las personas también comen insectos! Cerca de 2.000 millones de personas tienen insectos en el menú, como los chapulines en México.", s: ["Un oso hormiguero gigante puede comer decenas de miles de hormigas y termitas en un solo día.", "Las crías de muchos pájaros se alimentan casi solo de insectos.", "Cuando los insectos disminuyen, los animales que dependen de ellos también sufren."], ex: { t: "Cadena de la vida", m: "tiras de papel, cinta o plasticola, lápices de colores", p: ["En cada tira de papel, dibuja un ser vivo: Sol, planta, oruga, pájaro y halcón.", "Arma una cadena de papel en el orden correcto, uniendo al que es comido con el que come.", "Ahora saca el eslabón de la oruga: ¿qué les pasa al pájaro y al halcón? ¡La cadena se deshace! Todos dependen de todos."] }, at: "Tarjeta 26: la cadena alimentaria", m: "tarjetas, lápices de colores", p: ["Dibuja una cadena alimentaria con flechas, empezando por el Sol.", "Dibuja un oso hormiguero comiendo hormigas.", "Escribe: “¡Sin insectos, la cadena se rompe!”."], q: "¿Qué animal crees que más extrañaría a los insectos si desaparecieran?" } },

{ e: "🧵", art: { b: "🐛", s: ["🧵", "🍃", "🥚", "🏮"], c: ["#5A1B3A", "#E07AA0"] },
pt: { h: "Nina mostrou ao vovô o seu lenço preferido, macio e brilhante. “É de seda”, disse o vovô. “E sabe quem fez esse fio? Uma lagartinha! Há milhares de anos, na China, as pessoas descobriram que o casulo do bicho-da-seda era feito de um único fio, longuíssimo.”", t: "O bicho-da-seda", f: "O bicho-da-seda é a lagarta de uma mariposa que come folhas de amoreira. Quando chega a hora de se transformar, ele constrói um casulo enrolando em volta de si um único fio de seda, sem parar, por uns dois ou três dias. A China cria bichos-da-seda há milhares de anos, e o tecido de seda era tão valioso que deu nome a uma rota de comércio: a Rota da Seda.", x: "O fio de um único casulo pode ter perto de um quilômetro de comprimento! Para fazer uma camiseta de seda, são necessários centenas de casulos.", s: ["Por muito tempo, a China guardou em segredo como se fazia a seda.", "O Brasil está entre os países que produzem seda, principalmente no Paraná.", "A mariposa do bicho-da-seda quase não voa e depende das pessoas para viver."], ex: { t: "Um quilômetro de fio", m: "um novelo de lã ou barbante, uma fita métrica, um quintal ou corredor", p: ["Meça 10 metros de barbante e estique no chão ou no quintal.", "O fio de um casulo pode ser umas 100 vezes maior que esse barbante! Faça as contas: quantos quintais seriam?", "Agora enrole os 10 metros em volta de um lápis, bem juntinho, como o bicho-da-seda faz o casulo. Quanto tempo você levou?"] }, at: "Cartão 27: o bicho-da-seda", m: "cartões, lápis de cor, um pedacinho de linha", p: ["Desenhe um bicho-da-seda comendo uma folha de amoreira e, ao lado, um casulo.", "Cole um pedacinho de linha saindo do casulo.", "Escreva: “Um casulo, um fio de quase 1 quilômetro!”."], q: "Que roupas ou objetos da sua casa você acha que vieram da natureza?" },
en: { h: "Nina showed Grandpa her favorite scarf, soft and shiny. “It's silk,” said Grandpa. “And do you know who made that thread? A little caterpillar! Thousands of years ago, in China, people discovered that the silkworm's cocoon was made of one single, extremely long thread.”", t: "The silkworm", f: "The silkworm is the caterpillar of a moth that eats mulberry leaves. When it's time to transform, it builds a cocoon by winding one single silk thread around itself, nonstop, for about two or three days. China has raised silkworms for thousands of years, and silk cloth was so valuable that it gave its name to a trade route: the Silk Road.", x: "The thread from a single cocoon can be close to a kilometer (more than half a mile) long! Making one silk shirt takes hundreds of cocoons.", s: ["For a long time, China kept the secret of how silk was made.", "Today silk is produced in several countries, including India and Brazil.", "The silk moth can barely fly and depends on people to live."], ex: { t: "A kilometer of thread", m: "a ball of yarn or string, a tape measure, a yard or hallway", p: ["Measure 10 meters (about 33 feet) of string and stretch it out on the floor or in the yard.", "A cocoon's thread can be about 100 times longer than that string! Do the math: how many yards would that be?", "Now wind the 10 meters tightly around a pencil, like a silkworm making its cocoon. How long did it take you?"] }, at: "Card 27: the silkworm", m: "cards, colored pencils, a small piece of thread", p: ["Draw a silkworm eating a mulberry leaf and, next to it, a cocoon.", "Glue a small piece of thread coming out of the cocoon.", "Write: “One cocoon, one thread almost a kilometer long!”"], q: "What clothes or objects in your house do you think came from nature?" },
es: { h: "Nina le mostró al abuelo su pañuelo favorito, suave y brillante. “Es de seda”, dijo el abuelo. “¿Y sabes quién hizo ese hilo? ¡Una orugüita! Hace miles de años, en China, las personas descubrieron que el capullo del gusano de seda estaba hecho de un solo hilo larguísimo.”", t: "El gusano de seda", f: "El gusano de seda es la oruga de una polilla que come hojas de morera. Cuando llega el momento de transformarse, construye un capullo enrollando a su alrededor un único hilo de seda, sin parar, durante unos dos o tres días. China cría gusanos de seda desde hace miles de años, y la tela de seda era tan valiosa que le dio nombre a una ruta de comercio: la Ruta de la Seda.", x: "¡El hilo de un solo capullo puede medir cerca de un kilómetro! Para hacer una camisa de seda hacen falta cientos de capullos.", s: ["Durante mucho tiempo, China guardó en secreto cómo se hacía la seda.", "Hoy se produce seda en varios países, como India y Brasil.", "La polilla del gusano de seda casi no vuela y depende de las personas para vivir."], ex: { t: "Un kilómetro de hilo", m: "un ovillo de lana o cordel, una cinta métrica, un patio o pasillo", p: ["Mide 10 metros de cordel y estíralo en el piso o en el patio.", "¡El hilo de un capullo puede ser unas 100 veces más largo que ese cordel! Haz la cuenta: ¿cuántos patios serían?", "Ahora enrolla los 10 metros alrededor de un lápiz, bien apretados, como hace el gusano de seda con su capullo. ¿Cuánto tardaste?"] }, at: "Tarjeta 27: el gusano de seda", m: "tarjetas, lápices de colores, un pedacito de hilo", p: ["Dibuja un gusano de seda comiendo una hoja de morera y, al lado, un capullo.", "Pega un pedacito de hilo saliendo del capullo.", "Escribe: “¡Un capullo, un hilo de casi 1 kilómetro!”."], q: "¿Qué ropa u objetos de tu casa crees que vinieron de la naturaleza?" } },

{ e: "🏨", art: { b: "🏨", s: ["🐝", "🐞", "🌸", "🪵"], c: ["#5A3A1B", "#C28A4A"] },
pt: { h: "Nina leu numa revista que os insetos estão diminuindo em muitos lugares do mundo e ficou preocupada. “A gente pode ajudar?”, perguntou. “Pode, e começando hoje!”, respondeu o vovô. “Vamos construir um hotel de insetos para o quintal, com quartos para abelhas solitárias, joaninhas e outros hóspedes.”", t: "Ajudando os insetos", f: "Em várias partes do mundo, os cientistas perceberam que há menos insetos do que antes. As principais causas são a destruição de matas e jardins, o uso de venenos nas plantações e as mudanças no clima. A boa notícia é que pequenas atitudes ajudam muito: plantar flores, deixar um cantinho do jardim mais selvagem e evitar inseticidas.", x: "A maioria das abelhas do mundo não vive em colmeias: são abelhas solitárias, que fazem ninho sozinhas em buraquinhos de madeira, caules ocos e no chão. Um hotel de insetos oferece exatamente esses buraquinhos!", s: ["Flores de cores e formatos diferentes atraem polinizadores diferentes.", "Uma tampinha com água e pedrinhas serve de bebedouro para abelhas, sem risco de afogamento.", "Folhas secas no chão são casa e cobertor para muitos bichinhos no inverno."], ex: { t: "Hotel de insetos", m: "uma garrafa PET grande cortada (com um adulto), barbante, gravetos, canudos de papel ou bambus finos, pinhas, folhas secas, palha", p: ["Com um adulto, corte a garrafa em um tubo, sem o fundo e sem o gargalo.", "Encha o tubo bem apertado com bambus, canudos de papel, gravetos, pinhas e palha, formando muitos “quartinhos”.", "Pendure o hotel com barbante num lugar protegido da chuva, perto de flores. Observe nas próximas semanas quem vem se hospedar!"] }, at: "Cartão 28: o hotel", m: "cartões, lápis de cor", p: ["Desenhe o seu hotel de insetos com os hóspedes chegando.", "Faça uma lista de 3 coisas que a sua família pode fazer para ajudar os insetos.", "Escreva: “Insetos são bem-vindos!”."], q: "Que flores ou plantas você gostaria de plantar para os insetos?" },
en: { h: "Nina read in a magazine that insects are declining in many parts of the world and got worried. “Can we help?” she asked. “We can, starting today!” Grandpa answered. “Let's build an insect hotel for the yard, with rooms for solitary bees, ladybugs and other guests.”", t: "Helping insects", f: "In many parts of the world, scientists have noticed there are fewer insects than before. The main causes are the destruction of woods and gardens, the use of poisons on crops and changes in the climate. The good news is that small actions help a lot: planting flowers, leaving a corner of the garden a little wild and avoiding insecticides.", x: "Most of the world's bees don't live in hives: they're solitary bees, which nest alone in little holes in wood, hollow stems and the ground. An insect hotel offers exactly those little holes!", s: ["Flowers of different colors and shapes attract different pollinators.", "A bottle cap with water and pebbles makes a bee drinking fountain with no risk of drowning.", "Dry leaves on the ground are a home and a blanket for many critters in winter."], ex: { t: "Insect hotel", m: "a large plastic bottle cut open (with a grown-up), string, twigs, paper straws or thin bamboo, pine cones, dry leaves, straw", p: ["With a grown-up, cut the bottle into a tube, without the bottom or the neck.", "Pack the tube tightly with bamboo, paper straws, twigs, pine cones and straw, making lots of little “rooms.”", "Hang the hotel with string somewhere sheltered from rain, near flowers. Watch over the next few weeks to see who checks in!"] }, at: "Card 28: the hotel", m: "cards, colored pencils", p: ["Draw your insect hotel with guests arriving.", "Make a list of 3 things your family can do to help insects.", "Write: “Insects welcome!”"], q: "What flowers or plants would you like to plant for insects?" },
es: { h: "Nina leyó en una revista que los insectos están disminuyendo en muchos lugares del mundo y se preocupó. “¿Podemos ayudar?”, preguntó. “¡Sí, y empezando hoy!”, respondió el abuelo. “Vamos a construir un hotel de insectos para el patio, con cuartos para abejas solitarias, vaquitas y otros huéspedes.”", t: "Ayudando a los insectos", f: "En varias partes del mundo, los científicos notaron que hay menos insectos que antes. Las causas principales son la destrucción de montes y jardines, el uso de venenos en los cultivos y los cambios en el clima. La buena noticia es que las acciones pequeñas ayudan mucho: plantar flores, dejar un rinconcito del jardín más salvaje y evitar los insecticidas.", x: "¡La mayoría de las abejas del mundo no vive en colmenas: son abejas solitarias, que hacen nido solas en agujeritos de madera, tallos huecos y en el suelo! Un hotel de insectos ofrece justamente esos agujeritos.", s: ["Flores de colores y formas distintas atraen a polinizadores distintos.", "Una tapita con agua y piedritas sirve de bebedero para abejas, sin riesgo de que se ahoguen.", "Las hojas secas en el suelo son casa y manta para muchos bichitos en invierno."], ex: { t: "Hotel de insectos", m: "una botella de plástico grande cortada (con un adulto), cordel, ramitas, pajitas de papel o cañitas finas, piñas, hojas secas, paja", p: ["Con un adulto, corta la botella en un tubo, sin el fondo y sin el pico.", "Llena el tubo bien apretado con cañitas, pajitas de papel, ramitas, piñas y paja, formando muchos “cuartitos”.", "Cuelga el hotel con cordel en un lugar protegido de la lluvia, cerca de flores. ¡Observa en las próximas semanas quién viene a hospedarse!"] }, at: "Tarjeta 28: el hotel", m: "tarjetas, lápices de colores", p: ["Dibuja tu hotel de insectos con los huéspedes llegando.", "Haz una lista de 3 cosas que tu familia puede hacer para ayudar a los insectos.", "Escribe: “¡Insectos bienvenidos!”."], q: "¿Qué flores o plantas te gustaría plantar para los insectos?" } },

{ e: "🎨", art: { b: "🦋", s: ["🎨", "🔍", "📓", "⛵"], c: ["#3A1B4A", "#A07AC2"] },
pt: { h: "O vovô abriu um livro antigo cheio de pinturas de lagartas, casulos e borboletas sobre plantas coloridas. “Quem pintou isso foi uma mulher chamada Maria Sibylla Merian, há mais de 300 anos”, contou. “Naquela época, muita gente achava que os insetos nasciam do lixo. Ela observou com paciência e mostrou a verdade!”", t: "Cientistas dos insetos", f: "Os cientistas que estudam insetos se chamam entomólogos. Uma das pioneiras foi Maria Sibylla Merian, uma artista e naturalista alemã. Em 1699, ela viajou até o Suriname, na América do Sul, para observar e pintar insetos e plantas. Ela desenhou cada fase da vida: ovo, lagarta, casulo e borboleta, ajudando a mostrar como acontece a metamorfose.", x: "Até hoje são descobertas milhares de espécies novas de insetos todo ano! Muitas são encontradas por pessoas comuns, que fotografam bichinhos e compartilham com cientistas em aplicativos de ciência cidadã.", s: ["Para estudar os insetos sem machucá-los, os cientistas usam lupas, fotos e desenhos.", "Observar com paciência e anotar tudo é a ferramenta mais importante de um cientista.", "Uma das espécies de borboleta tem o nome de Merian em homenagem a ela."], ex: { t: "Um metro de mundo", m: "4 palitos ou gravetos, barbante de 4 metros, uma lupa, um caderno, um lápis", p: ["No quintal, na praça ou num jardim, marque um quadrado de 1 metro por 1 metro com os palitos e o barbante.", "Com a lupa, observe esse quadradinho por 15 minutos: no chão, nas folhas, debaixo das pedrinhas.", "Desenhe e conte todos os bichinhos que encontrar. Os cientistas fazem esse mesmo estudo para descobrir quantas vidas existem num lugar!"] }, at: "Cartão 29: o cientista", m: "cartões, lápis de cor", p: ["Desenhe, como Merian, as fases de um inseto sobre uma plantinha.", "Escreva quantos bichinhos você encontrou no seu metro de mundo.", "Escreva: “Observar com paciência!”."], q: "Se você fosse cientista, que bichinho gostaria de estudar e por quê?" },
en: { h: "Grandpa opened an old book full of paintings of caterpillars, cocoons and butterflies on colorful plants. “These were painted by a woman named Maria Sibylla Merian, more than 300 years ago,” he said. “Back then, many people thought insects were born from garbage. She watched patiently and showed the truth!”", t: "Insect scientists", f: "Scientists who study insects are called entomologists. One of the pioneers was Maria Sibylla Merian, a German artist and naturalist. In 1699, she traveled to Suriname, in South America, to observe and paint insects and plants. She drew every stage of life: egg, caterpillar, cocoon and butterfly, helping to show how metamorphosis happens.", x: "Even today, thousands of new insect species are discovered every year! Many are found by ordinary people who photograph little critters and share them with scientists on citizen-science apps.", s: ["To study insects without hurting them, scientists use magnifying glasses, photos and drawings.", "Watching patiently and writing everything down is a scientist's most important tool.", "One butterfly species is named after Merian in her honor."], ex: { t: "One meter of world", m: "4 sticks or twigs, 4 meters (13 feet) of string, a magnifying glass, a notebook, a pencil", p: ["In the yard, a park or a garden, mark out a square 1 meter by 1 meter (about 3 feet by 3 feet) with the sticks and string.", "With the magnifying glass, watch that little square for 15 minutes: on the ground, on the leaves, under the pebbles.", "Draw and count every critter you find. Scientists do this same study to find out how many living things are in a place!"] }, at: "Card 29: the scientist", m: "cards, colored pencils", p: ["Like Merian, draw the stages of an insect on a little plant.", "Write how many critters you found in your meter of world.", "Write: “Watch patiently!”"], q: "If you were a scientist, which critter would you like to study and why?" },
es: { h: "El abuelo abrió un libro antiguo lleno de pinturas de orugas, capullos y mariposas sobre plantas de colores. “Esto lo pintó una mujer llamada Maria Sibylla Merian, hace más de 300 años”, contó. “En esa época, mucha gente creía que los insectos nacían de la basura. ¡Ella observó con paciencia y mostró la verdad!”", t: "Científicos de los insectos", f: "Los científicos que estudian los insectos se llaman entomólogos. Una de las pioneras fue Maria Sibylla Merian, una artista y naturalista alemana. En 1699 viajó hasta Surinam, en América del Sur, para observar y pintar insectos y plantas. Dibujó cada etapa de la vida: huevo, oruga, capullo y mariposa, y ayudó a mostrar cómo ocurre la metamorfosis.", x: "¡Todavía hoy se descubren miles de especies nuevas de insectos cada año! Muchas las encuentran personas comunes, que fotografían bichitos y los comparten con científicos en aplicaciones de ciencia ciudadana.", s: ["Para estudiar los insectos sin lastimarlos, los científicos usan lupas, fotos y dibujos.", "Observar con paciencia y anotar todo es la herramienta más importante de un científico.", "Una especie de mariposa lleva el nombre de Merian en su honor."], ex: { t: "Un metro de mundo", m: "4 palitos o ramitas, 4 metros de cordel, una lupa, un cuaderno, un lápiz", p: ["En el patio, la plaza o un jardín, marca un cuadrado de 1 metro por 1 metro con los palitos y el cordel.", "Con la lupa, observa ese cuadradito durante 15 minutos: en el suelo, en las hojas, debajo de las piedritas.", "Dibuja y cuenta todos los bichitos que encuentres. ¡Los científicos hacen este mismo estudio para descubrir cuántas vidas hay en un lugar!"] }, at: "Tarjeta 29: el científico", m: "tarjetas, lápices de colores", p: ["Dibuja, como Merian, las etapas de un insecto sobre una plantita.", "Escribe cuántos bichitos encontraste en tu metro de mundo.", "Escribe: “¡Observar con paciencia!”."], q: "Si fueras científico o científica, ¿qué bichito te gustaría estudiar y por qué?" } },

{ e: "🏆", art: { b: "🔍", s: ["🐝", "🐞", "🕷️", "🎉"], c: ["#4A3A12", "#E0C04A"] },
pt: { h: "Na última noite, o vovô estendeu um lençol branco no quintal e acendeu uma lanterna forte atrás dele. “É o safári noturno do Clube da Lupa!”, anunciou. Aos poucos, mariposas, besouros e outros visitantes da noite foram pousando no lençol. Nina e Leo, com as lupas na mão, nem piscavam. Pipoca assistia da janela, muito interessada.", t: "Missão final: safári dos bichinhos", f: "Em 30 cartões, vocês conheceram abelhas que dançam, formigas agricultoras, cupins engenheiros, vaga-lumes que fazem luz fria, aranhas que tecem seda e lagartinhas que fazem fios de quase um quilômetro. Descobriram que os bichinhos, mesmo pequenos, sustentam a vida do planeta: polinizam, reciclam e alimentam muitos outros animais.", x: "Muitas mariposas se orientam pela luz da Lua. Por isso, uma lanterna perto de um lençol branco à noite atrai visitantes de vários tipos. Os cientistas usam esse mesmo truque para estudar os insetos noturnos!", s: ["No safári noturno, é só observar e fotografar: os visitantes vão embora sozinhos depois que a luz se apaga.", "Cada bichinho, por menor que seja, tem um papel importante na natureza.", "Um bom entomologista observa com respeito e deixa os bichos em paz."], ex: { t: "Safári noturno", m: "um lençol branco, barbante ou varal, uma lanterna forte, lupas, caderno, um adulto", p: ["Com um adulto, pendure o lençol branco num varal ao ar livre, logo depois do anoitecer.", "Acenda a lanterna apontada para o lençol e espere uns 20 minutos.", "Observe com a lupa quem chegou, desenhe ou fotografe, e conte os tipos diferentes. No fim, apague a luz e deixe os visitantes irem embora."] }, at: "Certificado de Entomologista Mirim", m: "o certificado do site, os 29 cartões da coleção, lápis de cor", p: ["Faça o cartão 30 com o seu bichinho favorito da série.", "Organize a coleção completa e mostre para a família.", "Imprima e preencha o certificado de Entomologista Mirim, e façam juntos a promessa: “Vou observar com respeito e proteger os bichinhos!”."], q: "De todos os bichinhos que você conheceu, qual foi o mais surpreendente?" },
en: { h: "On the last night, Grandpa hung a white sheet in the yard and turned on a bright flashlight behind it. “It's the Magnifier Club night safari!” he announced. Little by little, moths, beetles and other night visitors landed on the sheet. Nina and Leo, magnifying glasses in hand, didn't even blink. Popcorn watched from the window, very interested.", t: "Final mission: critter safari", f: "In 30 cards, you met bees that dance, farmer ants, engineer termites, fireflies that make cold light, spiders that spin silk and little caterpillars that make threads almost a kilometer long. You discovered that critters, small as they are, hold up life on the planet: they pollinate, recycle and feed many other animals.", x: "Many moths steer by the light of the Moon. That's why a light near a white sheet at night attracts all kinds of visitors. Scientists use this same trick to study nighttime insects!", s: ["On a night safari, you only watch and take photos: the visitors leave on their own once the light goes off.", "Every little critter, however small, has an important role in nature.", "A good entomologist watches respectfully and leaves the critters in peace."], ex: { t: "Night safari", m: "a white sheet, string or a clothesline, a bright flashlight, magnifying glasses, a notebook, a grown-up", p: ["With a grown-up, hang the white sheet on a clothesline outdoors, just after dark.", "Shine the flashlight on the sheet and wait about 20 minutes.", "Use the magnifying glass to see who showed up, draw or photograph them, and count the different kinds. At the end, turn off the light and let the visitors go."] }, at: "Junior Entomologist certificate", m: "the certificate from the site, the 29 collection cards, colored pencils", p: ["Make card 30 with your favorite critter from the series.", "Organize your complete collection and show it to your family.", "Print and fill in the Junior Entomologist certificate, and make the promise together: “I will watch with respect and protect the critters!”"], q: "Of all the critters you met, which was the most surprising?" },
es: { h: "La última noche, el abuelo colgó una sábana blanca en el patio y prendió una linterna potente detrás. “¡Es el safari nocturno del Club de la Lupa!”, anunció. De a poco, polillas, escarabajos y otros visitantes de la noche se fueron posando en la sábana. Nina y Leo, con las lupas en la mano, ni pestañeaban. Palomita miraba desde la ventana, muy interesada.", t: "Misión final: safari de bichitos", f: "En 30 tarjetas conocieron abejas que bailan, hormigas agricultoras, termitas ingenieras, luciérnagas que hacen luz fría, arañas que tejen seda y orugüitas que hacen hilos de casi un kilómetro. Descubrieron que los bichitos, aunque sean pequeños, sostienen la vida del planeta: polinizan, reciclan y alimentan a muchos otros animales.", x: "¡Muchas polillas se orientan con la luz de la Luna! Por eso, una linterna cerca de una sábana blanca de noche atrae visitantes de muchos tipos. Los científicos usan este mismo truco para estudiar los insectos nocturnos.", s: ["En el safari nocturno solo se observa y se fotografía: los visitantes se van solos cuando se apaga la luz.", "Cada bichito, por más pequeño que sea, tiene un papel importante en la naturaleza.", "Un buen entomólogo observa con respeto y deja a los bichos en paz."], ex: { t: "Safari nocturno", m: "una sábana blanca, cordel o tendedero, una linterna potente, lupas, cuaderno, un adulto", p: ["Con un adulto, cuelga la sábana blanca en un tendedero al aire libre, apenas oscurezca.", "Prende la linterna apuntando a la sábana y espera unos 20 minutos.", "Observa con la lupa quién llegó, dibuja o saca fotos, y cuenta los tipos distintos. Al final, apaga la luz y deja que los visitantes se vayan."] }, at: "Certificado de Entomólogo Junior", m: "el certificado del sitio, las 29 tarjetas de la colección, lápices de colores", p: ["Haz la tarjeta 30 con tu bichito favorito de la serie.", "Ordena la colección completa y muéstrasela a la familia.", "Imprime y completa el certificado de Entomólogo Junior, y hagan juntos la promesa: “¡Voy a observar con respeto y proteger a los bichitos!”."], q: "De todos los bichitos que conociste, ¿cuál fue el más sorprendente?" } },
];
